def p(text,style=body):return Paragraph(text,style)
def table(rows,widths):
 t=Table([[p(str(c),small) for c in row] for row in rows],colWidths=widths,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),HexColor('#deeeea')),('ROWBACKGROUNDS',(0,1),(-1,-1),[HexColor('#f3f7f6'),HexColor('#ffffff')]),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),3)]));return t
W,H=612,792
def page(items,n):
 stream=BytesIO()
 def footer(c,d):
  c.setStrokeColor(HexColor('#98bdb5'));c.line(48,44,W-48,44);c.setFont('Helvetica',8);c.setFillColor(HexColor('#243b43'));c.drawString(48,31,'3D Container Loading Optimisation');c.drawRightString(W-48,31,f'{n} / 6')
 SimpleDocTemplate(stream,pagesize=(W,H),leftMargin=48,rightMargin=48,topMargin=43,bottomMargin=57).build(items,onFirstPage=footer,onLaterPages=footer)
